<script setup lang="ts">
import {onMounted,ref} from 'vue'
import SupportView from './SupportView.vue'
import MissionFindingsPanel from '@/components/MissionFindingsPanel.vue'
import MissionDiagnosticsPanel from '@/components/MissionDiagnosticsPanel.vue'
import MissionVisitsPanel from '@/components/MissionVisitsPanel.vue'
import MissionPlanPanel from '@/components/MissionPlanPanel.vue'
import MissionCommentsPanel from '@/components/MissionCommentsPanel.vue'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
interface Mission {id:number;title:string;scope:string;starts_on:string;ends_on:string;status:string;version:number}
interface Member{id:number;name:string;role:string;status:string;version:number;assignment_status:string;starts_on:string;ends_on:string}
interface Workspace {mission:Mission;team:Member[];events:{id:number;action:string;reason:string;created_at:string}[];can_lead:boolean;can_admin:boolean}
const rows=ref<Mission[]>([]),workspace=ref<Workspace|null>(null),selected=ref<Member|null>(null),open=ref(false),confirm=ref(false),loading=ref(false),busy=ref(false),error=ref(''),dialogError=ref(''),notice=ref(''),action=ref('start'),reason=ref(''),agreed=ref(false),page=ref(1),last=ref(1)
const labels:Record<string,string>={proposed:'Proposée',accepted:'Acceptée',refused:'Refusée',cancelled:'Annulée',active:'En cours',suspended:'Suspendue',pending:'À approuver',approved:'Approuvé',revoked:'Retiré'}
const actionLabels:Record<string,string>={start:'Démarrer',suspend:'Suspendre',resume:'Reprendre',approved:'Approuver la participation',refused:'Refuser la participation',revoked:'Retirer la participation'}
async function load(){loading.value=true;error.value='';rows.value=[];try{const d=await request<{data:Mission[];last_page:number}>('/support/missions?page='+page.value);rows.value=d.data;last.value=d.last_page}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function view(id:number){loading.value=true;error.value='';try{workspace.value=await request<Workspace>('/support/missions/'+id);open.value=true}catch(e){workspace.value=null;error.value=(e as Error).message}finally{loading.value=false}}
function decide(value:string,member?:Member){action.value=value;selected.value=member||null;reason.value='';agreed.value=false;dialogError.value='';confirm.value=true}
async function execute(){busy.value=true;dialogError.value='';const id=workspace.value!.mission.id;try{await request(`/support/missions/${id}/`+(selected.value?`team/${selected.value.id}/decision`:'transition'),'POST',{version:selected.value?.version||workspace.value!.mission.version,...(selected.value?{decision:action.value}:{action:action.value}),reason:reason.value,confirmed:agreed.value});confirm.value=false;notice.value='Décision enregistrée et historisée.';await load();await view(id)}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><SupportView v-if="demoMode"/><section v-else class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 02 · MISSIONS</p><h1>Mes missions d’accompagnement</h1><p class="page-subtitle">Accès approuvés, pilotage et historique de l’officine sélectionnée.</p></div><button v-if="!demoMode" class="button secondary" :disabled="loading||busy" @click="load">Actualiser</button></div><div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><p v-if="loading" role="status">Chargement des missions…</p><div v-else-if="!error" class="panel"><div class="table-scroll"><table><thead><tr><th>MISSION</th><th>PÉRIODE</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><tr v-for="m in rows" :key="m.id"><td>{{m.title}}<span class="table-subtitle">#{{m.id}} · v{{m.version}}</span></td><td>{{m.starts_on}} → {{m.ends_on}}</td><td>{{labels[m.status]||m.status}}</td><td><button class="button secondary small" @click="view(m.id)">Voir la mission</button></td></tr><tr v-if="!rows.length"><td colspan="4" class="empty-state">Aucune mission dans votre périmètre approuvé.</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="page>=last" @click="page++;load()">Suivant</button></div></div><p class="module-disclaimer">Une proposition ou un rôle coordinateur ne suffit pas à lire une mission. Les intervenants nécessitent une affectation M1 et une participation de mission approuvées, actives et dans leur période.</p></div>
<AppModal v-model="open" :title="workspace?.mission.title||'Mission'" size="wide"><div v-if="workspace" class="form-body"><dl class="application-summary"><dt>Périmètre accepté</dt><dd>{{workspace.mission.scope}}</dd><dt>Période</dt><dd>{{workspace.mission.starts_on}} → {{workspace.mission.ends_on}}</dd><dt>État</dt><dd>{{labels[workspace.mission.status]||workspace.mission.status}} · v{{workspace.mission.version}}</dd></dl><div v-if="workspace.can_lead" class="heading-actions"><button v-if="workspace.mission.status==='accepted'" class="button primary" @click="decide('start')">Démarrer la mission</button><button v-if="workspace.mission.status==='active'" class="button secondary" @click="decide('suspend')">Suspendre la mission</button><button v-if="workspace.mission.status==='suspended'" class="button primary" @click="decide('resume')">Reprendre la mission</button></div><MissionFindingsPanel :mission-id="workspace.mission.id" :active="workspace.mission.status==='active'" @changed="view(workspace.mission.id)"/><MissionDiagnosticsPanel :mission-id="workspace.mission.id" :active="workspace.mission.status==='active'" @changed="view(workspace.mission.id)"/><MissionPlanPanel :mission-id="workspace.mission.id" :active="workspace.mission.status==='active'"/><MissionCommentsPanel :mission-id="workspace.mission.id"/><MissionVisitsPanel :mission-id="workspace.mission.id" :active="workspace.mission.status==='active'" @changed="view(workspace.mission.id)"/><h3>Équipe de mission</h3><p v-if="!workspace.team.length">Aucune participation proposée.</p><article v-for="m in workspace.team" :key="m.id" class="detail-card"><strong>{{m.name}} · {{m.role==='lead'?'Responsable':'Intervenant'}}</strong><p>{{labels[m.status]||m.status}} · M1 : {{labels[m.assignment_status]||m.assignment_status}} · {{m.starts_on}} → {{m.ends_on}}</p><div v-if="workspace.can_admin" class="heading-actions"><template v-if="m.status==='pending'"><button class="button primary small" @click="decide('approved',m)">Approuver la participation</button><button class="button secondary small" @click="decide('refused',m)">Refuser la participation</button></template><button v-if="m.status==='approved'" class="button secondary small" @click="decide('revoked',m)">Retirer la participation</button></div></article><RouterLink v-if="workspace.can_admin" class="text-link" to="/dashboard/accompagnateurs">Vérifier les affectations et permissions M1</RouterLink><h3>Historique partagé</h3><p v-for="e in workspace.events" :key="e.id">{{e.created_at}} · {{e.action}} · {{e.reason}}</p><p v-if="!workspace.events.length">Aucun événement opérationnel.</p></div><template #footer><button class="button secondary" @click="open=false">Fermer</button></template></AppModal>
<AppModal v-model="confirm" :title="actionLabels[action]||'Confirmer'" :busy="busy"><form id="mission-workspace-decision" class="form-body correction-form" @submit.prevent="execute"><p v-if="dialogError" class="alert error" role="alert">{{dialogError}}</p><p>{{workspace?.mission.title}} {{selected?'· '+selected.name:''}}</p><label>Motif de la décision<textarea v-model="reason" required maxlength="2000" rows="4"/></label><label class="checkbox-label"><input v-model="agreed" type="checkbox" required/>Je confirme explicitement cette décision.</label><p>Une participation approuvée ne remplace pas les permissions M1. Leur retrait ou expiration bloque immédiatement l’accès lors des requêtes suivantes.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="confirm=false">Annuler</button><button class="button primary" :disabled="busy" type="submit" form="mission-workspace-decision">Confirmer</button></template></AppModal></section></template>
